css:
.os { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.os-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.os-select { width: 100%; padding: 11px 38px 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background-color: #fff; background-image: linear-gradient(45deg, transparent 50%, #6b7280 50%), linear-gradient(135deg, #6b7280 50%, transparent 50%); background-position: calc(100% - 21px) 50%, calc(100% - 16px) 50%; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; font-size: 14px; color: #111827; -webkit-appearance: none; appearance: none; cursor: pointer;  }
.os-select:hover { border-color: #9ca3af; }
.os-select:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.fs { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
